mc(d,19,'Vì sao dùng các model khác nhau có thể hữu ích trong adversarial collaboration?','Blind spots khác nhau giúp tăng coverage kiểm tra','Ba bản sao cùng model luôn độc lập hoàn toàn','Model diversity loại bỏ mọi nhu cầu Judge','Nhiều model luôn rẻ và nhanh hơn một model','Khác training data có thể tạo góc nhìn khác, nhưng sequential critique thêm cost/latency nên cần cân giá trị.')
mc(d,21,'Vì sao parallel execution không mặc định nhanh hơn?','Dependencies, locks và merge conflict có thể triệt tiêu speedup','Mọi subtask tự động độc lập khi chạy async','Thời gian merge luôn bằng0','Số worker càng lớn luôn giảm latency tỷ lệ thuận','DAG dependencies, contention và aggregation tạo overhead; cần đo thay giả định parallel luôn thắng.')
mc(d,22,'Blackboard shared state và message passing khác nhau ở đánh đổi coordination nào?','Central state đơn giản nhưng cần bảo vệ concurrent writes; queue decouple thêm network latency','Blackboard không bao giờ có race vì mọi agent dùng LLM','Message passing không cần schema hay context bàn giao','Queue luôn giảm latency về 0 so với local state','Blackboard dùng state chung; message passing qua queue scale/decouple tốt hơn nhưng thêm truyền thông và handoff design.')
mc(d,22,'Handoff chỉ gửi partial context không đủ cho worker thường gây vấn đề nào?','Worker mất thông tin mục tiêu/ràng buộc nên chất lượng giảm','Tự tăng privacy và quality trong mọi task','Tự bảo đảm isolation đồng nghĩa đầy đủ bằng chứng','Chỉ đổi chi phí token mà không ảnh hưởng outcome','Context loss qua handoff là coordination failure; cần truyền đủ thông tin liên quan và trace được đường đi.')
mc(d,22,'Một worker timeout trong supervisor workflow nên có chính sách nào?','Retry worker khác hoặc fallback theo failure handling','Luôn đợi vô hạn vì worker có thể trả lời sau','Coi timeout như kết quả nghiệp vụ rỗng đã xác minh','Bỏ mọi log để tránh trace phức tạp','Supervisor cần detect timeout và retry/fallback thay để task treo hoặc hợp nhất kết quả giả.','apply')
mc(d,23,'Pre-initialize một agent pool rồi cấp việc qua queue nhằm mục tiêu nào?','Amortize init cost và kiểm soát concurrency','Tạo thêm model weights mỗi token sinh','Bỏ qua API rate limit nhờ có queue','Cho mọi request spawn vô hạn instance mới','Pool tái sử dụng instances và giới hạn số việc đồng thời, khác tạo agent mới không kiểm soát mỗi request.')
